import bodyParser from 'body-parser';
import * as dotenv from 'dotenv';

if (!process.env.DCOMPOSE) {
  dotenv.config();
}

import express from 'express';
import http from 'http';
import path from 'path';
import cors from 'cors';
import fs from 'fs';
import routes from './routes/routes';
import logger from '../logger';
import '../shim';
import { connectToMongo } from './db/mongoose';

/**
 * Configura el servidor Express, conectando middlewares, rutas y base de datos.
 * Arranca el servidor HTTP en el puerto especificado.
 */

const app = express();
const PORT = process.env.PORT || 5500;

(async () => {
  /**
 * Establece la conexión con la base de datos MongoDB.
 * Finaliza el proceso si no se puede conectar.
 */
  await connectToMongo();

  /**
 * Verifica y crea directorios y ficheros necesarios para el correcto funcionamiento
 * del servicio, tales como el contador de IDs y directorios de credenciales y logs.
 */

  (function initDirectoriesAndFiles() {
    const dataDir = path.join(__dirname, '..', 'data');
    const dirs = ['count', 'credentials', 'logs', 'status'];

    for (const dirName of dirs) {
      const dirPath = path.join(dataDir, dirName);
      if (!fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true });
        logger.info(`Directorio creado: ${dirPath}`);
      }
    }

    const countDir = path.join(dataDir, 'count');
    const idTxtPath = path.join(countDir, 'id.txt');
    if (!fs.existsSync(idTxtPath)) {
      fs.writeFileSync(idTxtPath, '0', 'utf-8');
      logger.info(`Archivo id.txt creado con "0" en ${idTxtPath}`);
    }
  })();

  app.set('view engine', 'ejs');
  app.set('views', path.join(__dirname, 'views'));

  app.use(cors());
  app.use(bodyParser.urlencoded({ extended: true }));
  app.use(bodyParser.json());
  app.use(express.static(path.join(__dirname, 'public')));

  app.use('/', routes);

  http.createServer(app).listen(PORT, () => {
    logger.info(`HTTP server listening on http://localhost:${PORT}`);
  });

})();

/**
 * Representa el estado de una credencial.
 * Incluye el ID de la credencial y su estado actual.
 */
export class CredStatus {
  credentialId: string;
  status: string;

/**
 * Crea una instancia de CredStatus.
 * @param credentialId Identificador de la credencial.
 * @param status Estado de la credencial (ej: 'issued', 'pending').
 * @throws Error si credentialId o status no son strings o están vacíos.
 */
  constructor(credentialId: string, status: string) {
    if (typeof credentialId !== 'string' || typeof status !== 'string') {
      throw new Error('Both credentialId and status must be strings');
    }

    if (!credentialId || !status) {
      throw new Error('Both credentialId and status are required');
    }
    this.credentialId = credentialId;
    this.status = status;
  }
}

import { Schema, model, Document } from 'mongoose';

export interface DIDDocument {
  issuerLabel: string;
  issuerDid: string;
  issuerKey: any;
  didDocument: any;
}

export interface DIDDocumentModel extends DIDDocument, Document {}

const DIDSchema = new Schema<DIDDocumentModel>({
  issuerLabel: { type: String, required: true, unique: true },
  issuerDid: { type: String, required: true },
  issuerKey: { type: Object, required: true },
  didDocument: { type: Object, required: true }
});

export const DIDModel = model<DIDDocumentModel>('DID', DIDSchema);

import express from 'express';
import {
  getscredx,
  upstatus,
  getcred,
  delcred,
  issue,
  ping,
  cr_did,
  didweb,
  schema,
  statusCallback,
  easterEgg,
  getIssuersDidsEndpoint
} from '../controllers/maincontroller';

const router = express.Router();

router.get('/ping', ping);

router.get('/did', cr_did);

router.get('/.well-known/did.json', didweb);

router.get('/issuer/entity/did.json', didweb);

router.get('/schema', schema);

router.get('/did/issuers', getIssuersDidsEndpoint);

// VC API CONTROLLERS
router.post('/credentials/issue', issue);

router.post('/statusCallback/:sessionId', statusCallback);

router.get('/credentials', getcred);

router.get('/credentials/:id(\\d+)', getscredx);

router.post('/credentials/status', upstatus);

router.delete('/credentials/:id(\\d+)', delcred);

router.get('/.hidden-easter-egg', easterEgg);

export default router;

import path from 'path';
import axios from 'axios';
import { v4 as uuidv4 } from 'uuid';
import logger from '../../logger';
import { FileRepository } from '../repositories/FileRepository';
import { MissingParameterError, CredentialIDError, NotFoundError, IssuerCoordError } from '../errors/errors';

/**
 * Servicio que gestiona la emisión, actualización de estado, borrado y consulta de credenciales.
 * Emite credenciales usando walt.id ya sea en modo OpenID4VC o firma directa.
 * Almacena las credenciales emitidas en ficheros locales.
 */
export class CredentialService {
  private mode: string;
  private waltidUrl: string;
  private fileRepository: FileRepository;

  constructor(fileRepository: FileRepository) {
    this.mode = process.env.MODE?.toLowerCase() || 'open';
    this.waltidUrl = process.env.WALTID_URL!;
    this.fileRepository = fileRepository;
  }

  /**
 * Emite una credencial del tipo indicado, firmándola con las llaves del issuer.
 * @param credentialType Tipo de credencial (Identity, Passport, Work).
 * @param issuerDid DID del issuer emisor.
 * @param issuerKey Llave del issuer para firmar la credencial.
 * @returns Objeto con `issuanceUrl` (en modo open) o `signedCredential` (en modo direct).
 */
  public async issueCredential(credentialType: string, issuerDid: string, issuerKey: any): Promise<any> {
    if (!credentialType) {
      throw new MissingParameterError('Missing parameter: type');
    }

    const credentialUuid = uuidv4();
    const credentialId = `urn:uuid:${credentialUuid}`;
    let credentialData: any;
    let credentialConfigurationId: string;

    switch (credentialType.toLowerCase()) {
      case 'identity':
        credentialConfigurationId = 'CustomIdentityCredential_jwt_vc_json';
        credentialData = { 
          "@context": [
            "https://www.w3.org/ns/credentials/v2",
            "https://www.w3.org/ns/credentials/examples/v2"
          ],
          "id": credentialId,
          "type": ["VerifiableCredential", "CustomIdentityCredential"],
          "issuer": {
            "id": issuerDid,
            "name": "Ministerio del Interior - Gobierno de España",
            "description": "Entidad emisora de documentos nacionales de identidad"
          },
          "name": "Documento Nacional de Identidad",
          "description": "Credencial verificable de identidad personal",
          "validFrom": "2024-12-08T10:19:28Z",
          "expirationDate": "2025-12-08T10:19:28Z",
          "category": "Identity",
          "credentialSubject": {
            "id": "did:web:localhost:6000",
            "dni": {
              "identifier": "12345678A",
              "givenName": "Mario",
              "familyName": "Perez",
              "gender": "M",
              "nationality": "ES",
              "birthDate": "1990-01-01",
              "nss": "123456789012",
              "photo": "https://example.com/images/12345678A_dni.jpg"
            }
          }
        };
        break;
      case 'passport':
        credentialConfigurationId = 'PassportCredential_jwt_vc_json';
        credentialData = {
          "@context": [
            "https://www.w3.org/ns/credentials/v2",
            "https://www.w3.org/ns/credentials/examples/v2"
          ],
          "id": credentialId,
          "type": ["VerifiableCredential", "PassportCredential"],
          "issuer": {
            "id": issuerDid,
            "name": "Ministerio de Asuntos Exteriores - España",
            "description": "Entidad emisora de pasaportes"
          },
          "name": "Pasaporte",
          "description": "Credencial verificable de pasaporte internacional.",
          "validFrom": "2024-01-01T00:00:00Z",
          "expirationDate": "2034-01-01T00:00:00Z",
          "category": "Identity",
          "credentialSubject": {
            "id": "did:web:persona.example.com",
            "givenName": "Mario",
            "familyName": "Perez",
            "birthDate": "1990-01-01",
            "nationality": "ES",
            "passportNumber": "X12345678",
            "issueDate": "2024-01-01",
            "issuingCountry": "España",
            "gender": "M",
            "placeOfBirth": "Madrid, España"
          }
        };
        break;
      case 'work':
        credentialConfigurationId = 'EmployerRegistrationCredential_jwt_vc_json';
        credentialData = {
          "@context": [
            "https://www.w3.org/ns/credentials/v2",
            "https://www.w3.org/ns/credentials/examples/v2"
          ],
          "id": credentialId,
          "type": ["VerifiableCredential", "EmployerRegistrationCredential"],
          "issuer": {
            "id": issuerDid,
            "name": "Ministerio de Trabajo y Economía Social - España",
            "description": "Entidad emisora del registro laboral de la empresa"
          },
          "name": "Registro del Empleador",
          "description": "Credencial que acredita el registro del empleador en la Seguridad Social",
          "validFrom": "2024-12-08T10:19:28Z",
          "expirationDate": "2026-12-08T10:19:28Z",
          "category": "EmployerRegistration",
          "credentialSubject": {
            "id": "did:web:empresa.example.com",
            "employerName": "Empresa de Servicios S.A.",
            "socialSecurityRegime": "Régimen General",
            "employerContributionAccountCode": "0111-2222-33-4444444444",
            "collectiveAgreements": [
              "Convenio Colectivo de Empresas de Servicios Generales",
              "Convenio Colectivo Sectorial"
            ]
          }
        };
        break;
      default:
        throw new Error('Tipo de credencial no soportado. Use "Identity", "Passport" o "Work".');
    }

    const status = this.mode === 'open' ? 'pending' : 'issued';
    const credentialsDir = path.join(__dirname, '..', '..', 'data', 'credentials');
    this.fileRepository.ensureDirectoryExists(credentialsDir);

    if (this.mode === 'open') {
      const authenticationMethod = 'PRE_AUTHORIZED';
      const payload = {
        issuerKey: issuerKey,
        issuerDid: issuerDid,
        credentialConfigurationId: credentialConfigurationId,
        credentialData: credentialData,
        mapping: {
          id: credentialData.id,
          issuer: { id: credentialData.issuer.id },
          credentialSubject: { id: credentialData.credentialSubject.id },
          issuanceDate: credentialData.validFrom,
          expirationDate: credentialData.expirationDate
        },
        authenticationMethod: authenticationMethod
      };

      const issueUrl_openid = `${this.waltidUrl}/openid4vc/jwt/issue`;
      const issueResponse = await axios.post<string>(issueUrl_openid, payload, {
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' }
      });

      if (issueResponse.status !== 200 && issueResponse.status !== 201) {
        throw new IssuerCoordError(`Failed to issue credential via OpenID. Status code: ${issueResponse.status}`);
      }

      const issuanceUrl = issueResponse.data;
      if (!issuanceUrl) {
        throw new Error('issuanceUrl not found in the response from walt.id');
      }

      const credentialToStore = {
        credentialData,
        status,
        issuanceUrl,
        issuanceTime: new Date().toISOString()
      };

      const credentialFilePath = path.join(credentialsDir, `credential_${credentialUuid}.json`);
      this.fileRepository.writeJSON(credentialFilePath, credentialToStore);

      return { issuanceUrl };
    } else {
      const directPayload = {
        issuerKey,
        issuerDid,
        subjectDid: issuerDid,
        credentialData
      };

      const issueUrl_direct = `${this.waltidUrl}/raw/jwt/sign`;
      const issueResponseDirect = await axios.post<string>(issueUrl_direct, directPayload, {
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' }
      });

      if (issueResponseDirect.status !== 200 && issueResponseDirect.status !== 201) {
        throw new IssuerCoordError(`Failed to issue credential via Direct Signing. Status code: ${issueResponseDirect.status}`);
      }

      const signedCredential = issueResponseDirect.data;
      if (!signedCredential) {
        throw new Error('Signed credential not found in the response from walt.id');
      }

      const credentialToStore = {
        credentialData,
        status,
        signedCredential,
        issuanceTime: new Date().toISOString()
      };

      const credentialFilePath = path.join(credentialsDir, `credential_${credentialUuid}.json`);
      this.fileRepository.writeJSON(credentialFilePath, credentialToStore);

      return { signedCredential };
    }
  }

  /**
 * Actualiza el estado de una credencial a 'issued' tras recibir un callback de estado.
 * Busca la credencial por sessionId en las issuanceUrl locales.
 * @param sessionId Identificador de sesión.
 * @param statusData Datos de estado recibidos del callback.
 */
  public updateCredentialStatusFromCallback(sessionId: string, statusData: any): void {
    const credentialsDir = path.join(__dirname, '..', '..', 'data', 'credentials');
    const files = this.fileRepository.listFiles(credentialsDir);

    let targetFilePath = '';
    let credentialData: any;

    for (const fileName of files) {
      const filePath = path.join(credentialsDir, fileName);
      const fileContent = this.fileRepository.readJSON(filePath);

      if (fileContent.issuanceUrl && fileContent.issuanceUrl.includes(sessionId)) {
        credentialData = fileContent;
        targetFilePath = filePath;
        break;
      }
    }

    if (!targetFilePath) {
      throw new NotFoundError(`Credential with sessionId ${sessionId} not found`);
    }

    credentialData.status = 'issued';
    this.fileRepository.writeJSON(targetFilePath, credentialData);
    logger.info(`Credential status updated to 'issued' for sessionId ${sessionId}`);
  }

  /**
 * Retorna todas las credenciales almacenadas en el sistema de ficheros.
 * @returns Lista de credenciales.
 */
  public getAllCredentials(): any[] {
    const credentialsDir = path.join(__dirname, '..', '..', 'data', 'credentials');
    const files = this.fileRepository.listFiles(credentialsDir);
    const credentials = [];
    for (const file of files) {
      const filePath = path.join(credentialsDir, file);
      const credential = this.fileRepository.readJSON(filePath);
      credentials.push(credential);
    }
    return credentials;
  }

  /**
 * Retorna una credencial específica por su ID numérico.
 * @param id ID numérico de la credencial.
 * @returns La credencial correspondiente.
 */
  public getCredentialById(id: string): any {
    const credentialsDir = path.join(__dirname, '..', '..', 'data', 'credentials');
    const filePath = path.join(credentialsDir, `credential_${id}.json`);
    return this.fileRepository.readJSON(filePath);
  }

  /**
 * Actualiza el estado de una credencial, almacenándolo en un fichero de estado separado.
 * @param credentialId Identificador completo de la credencial.
 * @param statusObj Objeto con `credentialId` y `status` representando el nuevo estado.
 */
  public updateCredentialStatus(credentialId: string, statusObj: { credentialId: string, status: string }): void {
    if (!credentialId || !statusObj) {
      throw new MissingParameterError('Missing required parameter');
    }

    const id = this.extractIdFromCredentialId(credentialId);

    const statusDir = path.join(__dirname, '..', '..', 'data', 'status');
    this.fileRepository.ensureDirectoryExists(statusDir);

    const statusFilePath = path.join(statusDir, `status${id}.json`);
    this.fileRepository.writeJSON(statusFilePath, statusObj);
  }

/**
 * Elimina una credencial del almacenamiento local.
 * @param id ID numérico de la credencial.
 */
  public deleteCredential(id: string): void {
    const credentialsDir = path.join(__dirname, '..', '..', 'data', 'credentials');
    const filePath = path.join(credentialsDir, `credential_${id}.json`);
    this.fileRepository.deleteFile(filePath);
  }

  /**
 * Extrae el ID final a partir de un identificador de credencial completo, asumiendo que el ID
 * está al final del string separado por '/'. Lanza un error si no se encuentra.
 * @param credentialId Identificador completo de la credencial.
 * @returns ID extraído (string).
 */
  private extractIdFromCredentialId(credentialId: string): string {
    const parts = credentialId.split('/');
    const _id = parts.pop();
    if (!_id) {
      throw new CredentialIDError('No ID found in the credential ID');
    }
    return _id;
  }
}

import fetch from 'node-fetch';
import logger from '../../logger';
import { DIDRepository } from '../repositories/DIDRepository';
import { NotFoundError } from '../errors/errors';

export class DIDService {
  private vaultTransitUrl: string;
  private waltidUrl: string;
  private didRepository: DIDRepository;

  constructor(didRepository: DIDRepository) {
    this.vaultTransitUrl = process.env.VAULT_TRANSIT_URL!;
    this.waltidUrl = process.env.WALTID_URL!;
    this.didRepository = didRepository;
  }

  /**
 * Crea un DID para un issuer dado, solicitando a walt.id y guardando en la BBDD.
 * @param roleId Identificador de rol del issuer.
 * @param secretId Secreto asociado al rol.
 * @param issuerLabel Etiqueta interna para identificar al issuer.
 * @returns Objeto con `issuerDid` y `issuerKey`.
 */
  public async createDidForIssuer(roleId: string, secretId: string, issuerLabel: string) {
    const requestBody = {
      key: {
        backend: 'tse',
        keyType: 'Ed25519',
        config: {
          server: this.vaultTransitUrl,
          auth: {
            roleId,
            secretId
          }
        }
      },
      did: {
        method: 'key'
      }
    };

    const onboardUrl = `${this.waltidUrl}/onboard/issuer`;
    const response = await fetch(onboardUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestBody),
    });

    if (!response.ok) {
      throw new Error(`Error al crear el DID para ${issuerLabel}: ${response.statusText}`);
    }

    const data = await response.json();
    const issuerDid = data.issuerDid;
    const issuerKey = data.issuerKey;

    const publicKeyJwk = { ...issuerKey.jwk };
    delete publicKeyJwk.d;

    const verificationMethod = {
      id: `${issuerDid}#key-1`,
      type: 'JsonWebKey2020',
      controller: issuerDid,
      publicKeyJwk
    };

    const didDocument = {
      '@context': 'https://www.w3.org/ns/did/v1',
      id: issuerDid,
      verificationMethod: [verificationMethod],
      authentication: [verificationMethod.id],
      assertionMethod: [verificationMethod.id],
    };

    logger.info(`Documento DID para ${issuerLabel} creado exitosamente`);

    await this.didRepository.createDID({
      issuerLabel,
      issuerDid,
      issuerKey,
      didDocument
    });

    return { issuerDid, issuerKey };
  }

  /**
 * Obtiene todos los DIDs de los issuers almacenados en la BBDD.
 * @returns Lista de strings con los issuerDids.
 */
  public async getIssuersDids(): Promise<string[]> {
    const allDids = await this.didRepository.getAllDIDs();
    return allDids.map(d => d.issuerDid);
  }

  /**
 * Carga el DID Document completo de un issuer en base a su etiqueta (issuerLabel).
 * @param issuer Nombre del issuer (ej: 'issuer1', 'issuer2', 'issuer3').
 * @returns Objeto JSON con el DID Document.
 */
  public async loadDidDocument(issuer: string): Promise<any> {
    const didRecord = await this.didRepository.getDIDByLabel(issuer);
    if (!didRecord) {
      throw new NotFoundError(`DID document for ${issuer} not found`);
    }
    return didRecord.didDocument;
  }
}

import { DIDModel, DIDDocument } from '../models/DIDModel';

/**
 * Repositorio para acceder y modificar DIDs en MongoDB.
 * Proporciona métodos para crear y obtener DIDs.
 */
export class DIDRepository {

/**
 * Crea y almacena un nuevo DID en la base de datos.
 * @param didData Datos del DID a almacenar.
 * @returns El documento DID creado.
 */
  async createDID(didData: DIDDocument): Promise<DIDDocument> {
    const did = new DIDModel(didData);
    return did.save();
  }

/**
 * Obtiene todos los DIDs almacenados en la base de datos.
 * @returns Array de documentos DID.
 */
  async getAllDIDs(): Promise<DIDDocument[]> {
    return DIDModel.find({});
  }

/**
 * Obtiene un DID específico buscando por su issuerLabel.
 * @param issuerLabel Etiqueta del issuer (ej: 'issuer1').
 * @returns Documento DID o null si no existe.
 */
  async getDIDByLabel(issuerLabel: string): Promise<DIDDocument | null> {
    return DIDModel.findOne({ issuerLabel });
  }
}

import fs from 'fs';
import path from 'path';
import { NotFoundError } from '../errors/errors';
import logger from '../../logger';

/**
 * Repositorio para operar sobre el sistema de ficheros,
 * permitiendo leer, escribir, listar y borrar ficheros JSON.
 */
export class FileRepository {

/**
 * Lee un fichero JSON y lo parsea a objeto.
 * @param filePath Ruta completa del fichero.
 * @returns El objeto leído.
 * @throws NotFoundError si no se encuentra el fichero.
 */
  public readJSON(filePath: string): any {
    try {
      const data = fs.readFileSync(filePath, 'utf8');
      return JSON.parse(data);
    } catch {
      throw new NotFoundError(`${filePath} has not been found`);
    }
  }

  /**
 * Escribe un objeto como JSON en el fichero especificado.
 * Sobrescribe el contenido existente.
 * @param filePath Ruta del fichero.
 * @param data Datos a escribir.
 */
  public writeJSON(filePath: string, data: any): void {
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
    logger.debug(`File ${filePath} written successfully`);
  }

  /**
 * Elimina un fichero del sistema de ficheros.
 * @param filePath Ruta del fichero a eliminar.
 * @throws NotFoundError si no se encuentra el fichero.
 */
  public deleteFile(filePath: string): void {
    try {
      fs.unlinkSync(filePath);
      logger.debug(`File ${filePath} deleted successfully`);
    } catch (err) {
      throw new NotFoundError(`${filePath} has not been found`);
    }
  }

  /**
 * Lista todos los ficheros en un directorio dado.
 * @param dirPath Ruta del directorio.
 * @returns Array de nombres de ficheros.
 * @throws NotFoundError si no se encuentra el directorio.
 */
  public listFiles(dirPath: string): string[] {
    try {
      return fs.readdirSync(dirPath);
    } catch (err) {
      throw new NotFoundError(`Directory ${dirPath} not found`);
    }
  }

  /**
 * Verifica si existe el directorio, y si no, lo crea recursivamente.
 * @param dirPath Ruta del directorio.
 */
  public ensureDirectoryExists(dirPath: string): void {
    if (!fs.existsSync(dirPath)) {
      fs.mkdirSync(dirPath, { recursive: true });
      logger.info(`Directory created: ${dirPath}`);
    }
  }

  /**
 * Comprueba si un fichero existe en el sistema.
 * @param filePath Ruta del fichero.
 * @returns true si existe, false si no.
 */
  public fileExists(filePath: string): boolean {
    return fs.existsSync(filePath);
  }
}

import { Request, Response } from 'express';
import logger from '../../logger';
import { DIDService } from '../services/DIDService';
import { CredentialService } from '../services/CredentialService';
import { FileRepository } from '../repositories/FileRepository';
import { DIDRepository } from '../repositories/DIDRepository'; 
import { MissingParameterError } from '../errors/errors';

const didRepository = new DIDRepository();
const didService = new DIDService(didRepository);
const fileRepository = new FileRepository();
const credentialService = new CredentialService(fileRepository);

/**
 * Responde con 'pong' para verificar que el servicio está vivo.
 * @route GET /ping
 */
export const ping = (_req: Request, res: Response) => {
  logger.info('Ping received');
  res.send('pong');
};

/**
 * Crea DIDs para tres issuers diferentes usando las credenciales (ROLE_ID, SECRET_ID)
 * obtenidas de entorno. Los guarda en la BBDD.
 * @route GET /did
 * @returns Objeto JSON con los DIDs creados.
 */
export const cr_did = async (_req: Request, res: Response) => {
  try {
    const roleIdIssuer1 = process.env.ROLE_ID_ISSUER1;
    const secretIdIssuer1 = process.env.SECRET_ID_ISSUER1;

    const roleIdIssuer2 = process.env.ROLE_ID_ISSUER2;
    const secretIdIssuer2 = process.env.SECRET_ID_ISSUER2;

    const roleIdIssuer3 = process.env.ROLE_ID_ISSUER3;
    const secretIdIssuer3 = process.env.SECRET_ID_ISSUER3;

    if (!roleIdIssuer1 || !secretIdIssuer1 || !roleIdIssuer2 || !secretIdIssuer2 || !roleIdIssuer3 || !secretIdIssuer3) {
      throw new Error('Faltan variables de entorno para ROLE_ID y SECRET_ID de los 3 issuers');
    }

    const issuer1Data = await didService.createDidForIssuer(roleIdIssuer1, secretIdIssuer1, 'issuer1');
    const issuer2Data = await didService.createDidForIssuer(roleIdIssuer2, secretIdIssuer2, 'issuer2');
    const issuer3Data = await didService.createDidForIssuer(roleIdIssuer3, secretIdIssuer3, 'issuer3');

    res.status(201).json({
      issuer1Did: issuer1Data.issuerDid,
      issuer2Did: issuer2Data.issuerDid,
      issuer3Did: issuer3Data.issuerDid
    });
  } catch (error: any) {
    logger.error('Error al crear los DIDs:', error);
    res.status(500).json({ error: error.message });
  }
};

/**
 * Obtiene el DID Document de un issuer específico.
 * @route GET /.well-known/did.json?issuer=issuer1|issuer2|issuer3
 * @param req query.issuer Identificador del issuer (opcional, por defecto issuer1).
 * @returns Objeto JSON con el DID Document.
 */
export const didweb = async (req: Request, res: Response) => {
  try {
    const issuer = (req.query.issuer as string) || 'issuer1';
    const data = await didService.loadDidDocument(issuer);
    logger.info(`DID Document para ${issuer} obtenido con éxito`);
    res.status(200).json(data);
  } catch (error: any) {
    logger.error('Error obteniendo DID Document:', error);
    res.status(500).json({ error: error.message });
  }
};

/**
 * Obtiene la lista de todos los issuerDids almacenados en la BBDD.
 * @route GET /did/issuers
 * @returns Lista de DIDs y, opcionalmente, una advertencia si hay menos de 3.
 */
export const getIssuersDidsEndpoint = async (_req: Request, res: Response) => {
  try {
    const dids = await didService.getIssuersDids();
    const response: any = { issuers: dids };
    if (dids.length < 3) {
      response.warning = "Menos de 3 issuers disponibles";
    }
    res.status(200).json(response);
  } catch (error: any) {
    logger.error('Error al obtener los DIDs de los issuers:', error);
    res.status(500).json({ error: error.message });
  }
};

/**
 * Devuelve un esquema JSON de ejemplo para validación.
 * @route GET /schema
 * @returns Objeto JSON con el esquema.
 */
export const schema = (_req: Request, res: Response) => {
  const schema = {
    $schema: 'http://json-schema.org/draft-07/schema#',
    type: 'object',
    properties: {
      name: { type: 'string' },
      identifier: { type: 'string', pattern: '^[0-9]{8}[A-Z]$' },
    },
    required: ['name', 'identifier'],
  };
  logger.info('Schema accedido con éxito');
  res.status(200).json(schema);
};

/**
 * Emite una credencial del tipo especificado (Identity, Passport o Work).
 * Hace uso del DID y la llave del issuer correspondiente, previamente almacenados en la BBDD.
 * @route POST /credentials/issue
 * @param req.body.type Tipo de credencial a emitir.
 * @returns URL de emisión o credencial firmada dependiendo del modo (open o direct).
 */
export const issue = async (req: Request, res: Response) => {
  try {
    const credentialType = req.body.type;
    if (!credentialType) {
      throw new MissingParameterError('Missing parameter: type');
    }

    const issuerLabel = credentialType.toLowerCase() === 'identity' ? 'issuer1'
      : credentialType.toLowerCase() === 'passport' ? 'issuer2'
      : credentialType.toLowerCase() === 'work' ? 'issuer3'
      : null;

    if (!issuerLabel) {
      throw new Error('Tipo de credencial no soportado. Use "Identity", "Passport" o "Work".');
    }

    const didRecord = await didRepository.getDIDByLabel(issuerLabel);
    if (!didRecord) {
      throw new MissingParameterError(`No se encontró el DID para ${issuerLabel}, por favor primero llame a /did`);
    }

    const issuerDid = didRecord.issuerDid;
    const issuerKey = didRecord.issuerKey;

    const responseData = await credentialService.issueCredential(credentialType, issuerDid, issuerKey);
    res.status(200).json(responseData);
  } catch (error: any) {
    logger.error('Error emitiendo credencial:', error);
    if (error.response) {
      res.status(error.response.status).json(error.response.data);
    } else if (error.code && error.code === 400) {
      res.status(400).json({ message: error.message });
    } else {
      res.status(500).json({ message: 'Internal Server Error', error: error.message });
    }
  }
};

/**
 * Procesa una devolución de estado (callback) desde el servicio de emisión,
 * actualizando el estado de la credencial a 'issued'.
 * @route POST /statusCallback/:sessionId
 * @param req.params.sessionId Identificador de sesión de emisión.
 */
export const statusCallback = async (req: Request, res: Response) => {
  try {
    const sessionId = req.params.sessionId;
    if (!sessionId) {
      throw new Error('sessionId not found in the callback URL');
    }

    credentialService.updateCredentialStatusFromCallback(sessionId, req.body);
    res.status(200).send('Status callback processed successfully');
  } catch (error: any) {
    logger.error('Error procesando status callback:', error);
    res.status(500).json({ error: error.message });
  }
};

/**
 * Obtiene todas las credenciales almacenadas localmente en el sistema de ficheros.
 * @route GET /credentials
